import sys, unicodedata as u, json, platform, hashlib, struct
from pathlib import Path
assert sys.version_info[:3] == (3,14,7) and u.unidata_version == '16.0.0'
n = u.ucd_3_2_0
rows=[]
hash=hashlib.sha256()
for p in range(0x110000):
    result=list(map(ord,n.normalize('NFKC',chr(p))))
    hash.update(struct.pack('<I',len(result)))
    for q in result: hash.update(struct.pack('<I',q))
    if result != [p]: rows.append([p,result])
seq = [[0x41,0x30a,0x301],[0x61,0x315,0x300],[0x301,0x323,0x300],[0x1100,0x1161,0x11a8],[0xac00,0x11a8],[0x41,0x301,0x30a],[0x41,0x345,0x30a],[0xd835,0xdc00],[0xd800,0x301,0xdc00],[0x1e9e,0x1ccd6],[0x2f868,0x2f874,0x2f91f,0x2f95f,0x2f9bf],[0xf951],[]]
# Verify interactions across every nonzero combining class with starters,
# blockers of equal class, and decomposable characters (including Hangul).
marks={}
for p in range(0x110000):
    cc=n.combining(chr(p))
    if cc: marks.setdefault(cc,p)
for a in marks.values():
    for b in marks.values():
        seq.append([0x41,a,b,0x30a,0xfb03,0x1100,0x1161,0x11a8])
data={'version':sys.version,'platform':platform.platform(),'unicode':u.unidata_version,'normalizationUnicode':n.unidata_version,'executable':sys.executable,'singlePointSha256':hash.hexdigest(),'singlePoints':rows,'sequences':[[s,list(map(ord,n.normalize('NFKC',''.join(map(chr,s)))))] for s in seq]}
Path('packages/safe-python/src/runtime/__snapshots__/normalization-3.2-3.14.7.json').write_text(json.dumps(data,separators=(',',':'))+'\n')
print(len(rows),len(seq),hash.hexdigest())
corpus=Path('/tmp/safe-python-NormalizationTest-3.2.0.txt').read_bytes()
assert hashlib.sha256(corpus).hexdigest()=='c4513869bb7098d19838be4a1fd5d760843c5804bfe03bd6bbb20623ceb6e57d'
corpus_hash=hashlib.sha256(); count=0
for line in corpus.decode().splitlines():
    body=line.split('#')[0].strip()
    if not body or body.startswith('@'): continue
    fields=body.split(';')[:5]
    expected=[int(p,16) for p in fields[3].split()]
    for field in fields:
        source=''.join(chr(int(p,16)) for p in field.split())
        result=list(map(ord,n.normalize('NFKC',source)))
        assert result==expected, (field,result,expected)
        corpus_hash.update(struct.pack('<I',len(result)))
        for p in result: corpus_hash.update(struct.pack('<I',p))
        count+=1
print('Official corpus',count,corpus_hash.hexdigest())
data['normalizationTest']={'url':'https://www.unicode.org/Public/3.2-Update/NormalizationTest-3.2.0.txt','sha256':hashlib.sha256(corpus).hexdigest(),'text':corpus.decode(),'invocations':count,'resultSha256':corpus_hash.hexdigest()}
data['oracleSource']=Path(__file__).read_text()
Path('packages/safe-python/src/runtime/__snapshots__/normalization-3.2-3.14.7.json').write_text(json.dumps(data,separators=(',',':'))+'\n')
